import os
import threading

from flask import Flask, jsonify, request
from transformers import pipeline

MODEL_DIR = "/app/model_cache/sentiment_model"

app = Flask(__name__)

_classifier = None
_lock = threading.Lock()


def get_classifier():
    global _classifier
    if _classifier is None:
        with _lock:
            if _classifier is None:
                _classifier = pipeline(
                    "sentiment-analysis",
                    model=MODEL_DIR,
                    tokenizer=MODEL_DIR,
                    device=-1,
                )
    return _classifier


@app.get("/health")
def health():
    return jsonify({"status": "ok"})


@app.post("/sentiment")
def sentiment():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"error": "Request body must be a JSON object"}), 400

    text = data.get("text")
    if text is None:
        return jsonify({"error": "Missing required field 'text'"}), 400
    if not isinstance(text, str):
        return jsonify({"error": "Field 'text' must be a string"}), 400
    if not text.strip():
        return jsonify({"error": "Field 'text' must not be empty"}), 400

    try:
        result = get_classifier()(text, truncation=True, max_length=512)[0]
    except Exception as exc:  # pragma: no cover - defensive
        return jsonify({"error": f"Inference failed: {exc}"}), 400

    label = str(result["label"]).lower()
    score = float(result["score"])
    if label == "positive":
        confidence = {"positive": score, "negative": 1.0 - score}
        sentiment = "positive"
    elif label == "negative":
        confidence = {"positive": 1.0 - score, "negative": score}
        sentiment = "negative"
    else:
        return jsonify({"error": f"Unexpected model label: {result['label']}"}), 400

    return jsonify({"sentiment": sentiment, "confidence": confidence})


if __name__ == "__main__":
    get_classifier()
    app.run(host="0.0.0.0", port=5000, threaded=True)

