import os
import threading

import torch
from flask import Flask, jsonify, request
from transformers import DistilBertForSequenceClassification, DistilBertTokenizer

MODEL_DIR = "/app/model_cache/sentiment_model"

app = Flask(__name__)

_model = None
_tokenizer = None
_id2label = None
_lock = threading.Lock()


def get_model():
    global _model, _tokenizer, _id2label
    if _model is None:
        with _lock:
            if _model is None:
                tokenizer = DistilBertTokenizer(
                    vocab_file=os.path.join(MODEL_DIR, "vocab.txt"),
                    do_lower_case=True,
                )
                model = DistilBertForSequenceClassification.from_pretrained(MODEL_DIR)
                model.eval()
                _tokenizer = tokenizer
                _model = model
                _id2label = {int(k): str(v).lower() for k, v in model.config.id2label.items()}
    return _model, _tokenizer, _id2label


def classify(text):
    model, tokenizer, id2label = get_model()
    inputs = tokenizer(text, return_tensors="pt", truncation=True, max_length=512)
    with torch.no_grad():
        logits = model(**inputs).logits
    probs = torch.softmax(logits, dim=-1)[0]
    scores = {id2label[i]: float(probs[i]) for i in range(probs.shape[0])}
    positive = scores.get("positive", 0.0)
    negative = scores.get("negative", 0.0)
    sentiment = "positive" if positive >= negative else "negative"
    return {
        "sentiment": sentiment,
        "confidence": {"positive": positive, "negative": negative},
    }


@app.get("/health")
def health():
    return jsonify({"status": "ok"})


@app.post("/sentiment")
def sentiment():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"error": "Request body must be a JSON object"}), 400

    text = data.get("text")
    if text is None:
        return jsonify({"error": "Missing required field 'text'"}), 400
    if not isinstance(text, str):
        return jsonify({"error": "Field 'text' must be a string"}), 400
    if not text.strip():
        return jsonify({"error": "Field 'text' must not be empty"}), 400

    try:
        return jsonify(classify(text))
    except Exception as exc:
        return jsonify({"error": f"Inference failed: {exc}"}), 400


if __name__ == "__main__":
    get_model()
    app.run(host="0.0.0.0", port=5000, threaded=True)

